-- Resources content for switching rundowns that came from an imported program log
-- (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- Updates the one-time clock change guide and adds a release note.

select private.rc_release_guide(
  p_slug => 'log-one-time-clock-change',
  p_tool_key => 'log',
  p_title => 'Changing a program''s clock for a few days',
  p_summary => 'Give a program a different clock on certain dates, such as FPREN storm coverage, and switch rundowns that were already built.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 60,
  p_version_note => 'Imported rundowns can be switched; notices for unplaced credits and released DAD logs',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a one-time change when a program needs a different clock for a set of dates, for example FPREN Phase I storm coverage. The normal weekly schedule stays as it is, and the one-time change replaces it on the dates you choose."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add the change"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program from "},{"type":"text","text":"Programs","marks":[{"type":"link","attrs":{"href":"/log/programs"}}]},{"type":"text","text":", then select "},{"type":"text","text":"+ Add a time","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set the entry type to "},{"type":"text","text":"One-time change","marks":[{"type":"bold"}]},{"type":"text","text":", choose the clock, and give the start and end dates, the air time and the length. A one-time change covers every day between its dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Save. On those dates, Today, the week view and any new rundown use this clock instead of the normal one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Switch rundowns that already exist"}]},{"type":"paragraph","content":[{"type":"text","text":"Traffic can build rundowns weeks ahead, so some of those dates may already have a rundown on the old clock. When that is so, the program page shows a notice that lists the dates, with a "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":" button."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Switching keeps each old rundown as a record and builds a new one on the clock now in force. The old rundown is marked as replaced and can't be started, edited or submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a rundown that hasn't started and has nothing recorded on it is switched. One that is on air, or has recorded outcomes, is left as it is."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rundowns built from an imported program log are switched the same way as the others. Where the rundown came from doesn't matter, only whether it has started or has anything recorded on it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens to underwriting"}]},{"type":"paragraph","content":[{"type":"text","text":"Any underwriting credit already placed on a replaced rundown is recorded as missed, with the reason Special coverage. Each one appears in Traffic's exception list, where staff decide on a makegood or a waiver. Nothing is placed again automatically, and nothing is counted as aired. Credits that came from an imported log have no Traffic placement behind them, so they can't raise an exception. The notice after switching tells you how many there were. They stay on the old rundown, and you add them to the new one if they still apply."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"DAD"}]},{"type":"paragraph","content":[{"type":"text","text":"If a date already has a released DAD log, the notice after switching names the date. The DAD log screen also marks that release as out of date. Traffic needs to release a new version, because DAD plays what was released."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Going back"}]},{"type":"paragraph","content":[{"type":"text","text":"To end a change early, shorten its end date or remove the entry, then select "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":" again on the program page. Exceptions that were already raised stay open for Traffic to resolve."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On Today, a program with a one-time change shows one row, labelled One-time change, not two."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Holiday is no longer an entry type. A holiday that needs a different clock is a one-time change; one that is only automated is set under Automation."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-09-log-switch-imported-rundowns',
  p_tool_key => 'log',
  p_released_on => '2026-10-09',
  p_title => 'Rundowns from an imported log can be switched to a new clock',
  p_guide_slugs => array['log-one-time-clock-change'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Switching a program's rundowns to a one-time clock now includes rundowns built from an imported program log, as long as they haven't started and have nothing recorded. The notice after switching also reports credits with no Traffic placement, which can't raise an exception, and any date that already has a released DAD log."}]}]}$body$
);
